import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { renderFlow } from "@agent-flows/core";
import { describe, expect, it } from "vitest";
import { assistantFlow } from "./assistant.js";
import { TARGETS } from "./kit.js";
const REPO_ROOT = join(__dirname, "..", "..", "..");
const ASSISTANT_PATHS = {
    claude: "bitfab-claude-plugin/skills/assistant/SKILL.md",
    cursor: "bitfab-cursor-plugin/skills/bitfab-assistant/SKILL.md",
    codex: "bitfab-codex-plugin/skills/assistant/SKILL.md",
    amp: "bitfab-amp-plugin/skills/assistant/SKILL.md",
};
describe("retired assistant flow", () => {
    for (const [targetName, path] of Object.entries(ASSISTANT_PATHS)) {
        it(`renders one skill file matching the committed ${targetName} skill`, () => {
            const files = renderFlow(assistantFlow, TARGETS[targetName]);
            expect(files).toHaveLength(1);
            const committed = readFileSync(join(REPO_ROOT, path), "utf8");
            expect(files[0]?.content).toBe(committed);
        });
    }
    it("declares no commands and no tools, so the skill cannot start work", () => {
        expect(assistantFlow.commands).toEqual({});
        expect(assistantFlow.tools).toEqual({});
    });
    it("tells the user to ask their agent directly, with examples, and points new instrumentation at setup", () => {
        const rendered = readFileSync(join(REPO_ROOT, ASSISTANT_PATHS.claude), "utf8");
        expect(rendered).toContain("has been retired");
        expect(rendered).toContain("just tell your agent what you want");
        expect(rendered).toContain("For example:");
        expect(rendered).toContain("`/bitfab:setup`");
    });
    it("only triggers when the user names the command, never on ordinary trace work", () => {
        const description = assistantFlow.frontmatter.description;
        expect(description).toMatch(/^Retired\./);
        expect(description).toContain("Never use it for requests about traces");
        expect(description).not.toContain("TRIGGER when");
    });
    it("leaves no Claude phase sub-skills behind", () => {
        const skillDirs = readdirSync(join(REPO_ROOT, "bitfab-claude-plugin", "skills"));
        expect(skillDirs.filter((dir) => dir.startsWith("assistant-"))).toEqual([]);
        expect(existsSync(join(REPO_ROOT, "bitfab-claude-plugin/skills/assistant"))).toBe(true);
    });
});
